const input = $json.body ?? $json;
const outcome = String(input.negotiation_outcome ?? input.outcome ?? input.decision ?? '').toLowerCase();
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const dynamicMao = Number(input.dynamic_mao ?? input.adjusted_mao ?? input.mao);
const askingPrice = Number(input.asking_price);
const lastOffer = Number(input.last_offer_price ?? input.offer_price ?? input.accepted_price);
const attempts = Number(input.reengagement_attempts ?? input.follow_up_attempts ?? 0);
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const dnc = Boolean(input.dnc ?? input.do_not_contact);
const identityOk = Boolean(dealId && leadId && propertyId);
const maxAttempts = Number(input.max_reengagement_attempts ?? 3);

let status = 'needs_review';
let action = 'human_review';
let nextWorkflow = 'WF-126';
let channel = input.preferred_channel ?? input.channel ?? 'sms';
let cadence = 'review';
let humanReview = true;

if (!identityOk || blockers.length || dnc) {
  status = dnc ? 'do_not_contact' : 'blocked';
  action = dnc ? 'suppress_contact' : 'human_review';
  nextWorkflow = 'WF-126';
} else if (attempts >= maxAttempts) {
  status = 'reengagement_exhausted';
  action = 'pause_and_recycle';
  nextWorkflow = 'WF-126';
  humanReview = true;
} else if (['rejected','seller_rejected','declined','walk_away','walkaway','timeout','no_response','silence','rejection_reengagement','walk_away_reengagement','reengagement'].includes(outcome)) {
  status = 'reengagement_ready';
  action = attempts === 0 ? 'first_reengagement' : 'follow_up_reengagement';
  nextWorkflow = 'WF-262';
  cadence = attempts === 0 ? '24h' : attempts === 1 ? '72h' : '7d';
  humanReview = false;
} else {
  status = 'needs_review';
  action = 'human_review';
}

const messageContext = {
  reason: outcome || 'negotiation ended without agreement',
  last_offer_price: Number.isFinite(lastOffer) ? lastOffer : null,
  asking_price: Number.isFinite(askingPrice) ? askingPrice : null,
  dynamic_mao: Number.isFinite(dynamicMao) ? dynamicMao : null,
  reengagement_attempts: attempts,
  max_reengagement_attempts: maxAttempts,
  channel,
  cadence
};

return [{ json: {
  ...input,
  workflow_id: 'WF-261',
  workflow_name: 'Rejection / Walk-Away / Timeout → Seller Re-engagement Controller',
  status,
  action,
  next_workflow: nextWorkflow,
  human_review_required: humanReview,
  reengagement: {
    eligible: status === 'reengagement_ready',
    attempt_number: attempts + 1,
    cadence,
    channel,
    message_context: messageContext
  },
  contact_suppressed: dnc,
  identity_valid: identityOk,
  blockers,
  crm_activity: {
    activity_type: 'seller_reengagement_routing',
    workflow_id: 'WF-261',
    action,
    status,
    next_workflow: nextWorkflow,
    attempt_number: attempts + 1
  }
} }];
